13	import com.example.starter.incident.dto.Requests.ReportRequest;
14	import com.example.starter.incident.dto.Requests.StatusRequest;
15	import com.example.starter.incident.dto.Requests.TakeoverRequest;
16	import com.example.starter.incident.dto.Requests.TransferAcceptRequest;
17	import com.example.starter.incident.dto.Requests.TransferRequest;
18	import com.example.starter.incident.dto.Responses.ActionView;
19	import com.example.starter.incident.dto.Responses.HistoryView;
20	import com.example.starter.incident.dto.Responses.IncidentView;
21	import com.example.starter.incident.dto.Responses.StatusChangeView;
22	import com.example.starter.incident.dto.Responses.TransferView;
23	import com.fasterxml.jackson.core.JsonProcessingException;
24	import com.fasterxml.jackson.databind.ObjectMapper;
25	import org.springframework.dao.DuplicateKeyException;
26	import org.springframework.stereotype.Service;
27	import org.springframework.transaction.annotation.Transactional;
28	
29	/**
30	 * 事件指挥核心服务。
31	 * 并发约定：所有写接口先 SELECT ... FOR UPDATE 锁定事件行，同事务内完成
32	 * 幂等键占位、业务校验与写入，保证并发请求按事务提交顺序生效。
33	 * 幂等约定：commandKey 全局唯一，同键同参重放首次响应，同键改参返回 409。
34	 */
35	@Service
36	public class IncidentService {
37	
38	    private static final String SEP = "\\u001F";
39	
40	    private final IncidentRepository incidents;
41	    private final CommandKeyRepository commandKeys;
42	    private final ObjectMapper objectMapper;
43	
44	    public IncidentService(IncidentRepository incidents, CommandKeyRepository commandKeys,
45	                           ObjectMapper objectMapper) {
46	        this.incidents = incidents;
47	        this.commandKeys = commandKeys;
48	        this.objectMapper = objectMapper;
49	    }
50	
51	    /**
52	     * 事件上报：初始状态 REPORTED，无指挥人。incidentKey 重复返回 409。
53	     */
54	    @Transactional
55	    public IncidentView report(ReportRequest req) {
56	        String incidentKey = requireText(req.incidentKey(), "incidentKey");
57	        String severity = requireText(req.severity(), "severity");
58	        if (!severity.matches("S[1-4]")) {
59	            throw ApiException.badRequest("severity 必须为 S1~S4");
60	        }
61	        String summary = requireText(req.summary(), "summary");
62	        String reporter = requireText(req.reporter(), "reporter");
63	        if (incidents.findByKey(incidentKey).isPresent()) {
64	            throw ApiException.conflict("incidentKey 已存在: " + incidentKey);
65	        }
66	        Instant now = Instant.now();
67	        Incident incident = new Incident(0L, incidentKey, severity, summary, reporter,
68	                IncidentStatus.REPORTED, null, now, now);
69	        long id;
70	        try {
71	            id = incidents.insert(incident);
72	        } catch (DuplicateKeyException e) {
73	            throw ApiException.conflict("incidentKey 已存在: " + incidentKey);
74	        }
75	        incidents.insertStatusChange(new StatusChange(0L, id, null, IncidentStatus.REPORTED, reporter, now));
76	        return toView(incidents.findByKey(incidentKey).orElseThrow(), null);
77	    }
78	
79	    /**
80	     * 首次接管：REPORTED → COMMANDING，记录当前指挥人。
81	     */
82	    @Transactional
83	    public IncidentView takeover(String incidentKey, String actor, TakeoverRequest req) {
84	        String commandKey = requireText(req.commandKey(), "commandKey");
85	        Incident incident = lockIncident(incidentKey);
86	        return runIdempotent(commandKey, "takeover", hash(incidentKey, actor), IncidentView.class,
87	                () -> {
88	                    if (incident.status() != IncidentStatus.REPORTED) {
89	                        throw ApiException.illegalTransition(
90	                                "仅 REPORTED 状态可接管，当前状态: " + incident.status());
91	                    }
92	                    Instant now = Instant.now();
93	                    incidents.updateState(incident.id(), IncidentStatus.COMMANDING, actor, now);
94	                    incidents.insertStatusChange(new StatusChange(0L, incident.id(),
95	                            IncidentStatus.REPORTED, IncidentStatus.COMMANDING, actor, now));
96	                    return toView(incidents.findByKey(incidentKey).orElseThrow(), null);
97	                });
98	    }
99	
100	    /**
101	     * 发起交接：仅当前指挥人可发起，目标人必须不同；RESOLVED/CLOSED 禁止发起。
102	     */
103	    @Transactional
104	    public TransferView initiateTransfer(String incidentKey, String actor, TransferRequest req) {
105	        String commandKey = requireText(req.commandKey(), "commandKey");
106	        String toCommander = requireText(req.toCommander(), "toCommander");
107	        Incident incident = lockIncident(incidentKey);
108	        return runIdempotent(commandKey, "transfer_initiate", hash(incidentKey, actor, toCommander),
109	                TransferView.class, () -> {
110	                    requireCommander(incident, actor);
111	                    if (incident.status() == IncidentStatus.RESOLVED
112	                            || incident.status() == IncidentStatus.CLOSED) {
113	                        throw ApiException.illegalTransition(
114	                                incident.status() + " 状态不允许发起交接");
115	                    }
116	                    if (incident.status() == IncidentStatus.REPORTED) {
117	                        throw ApiException.illegalTransition("尚未接管的事件不能发起交接");
118	                    }
119	                    if (toCommander.equals(incident.commander())) {
120	                        throw ApiException.badRequest("目标指挥人必须与当前指挥人不同");
121	                    }
122	                    if (incidents.findPendingTransfer(incident.id()).isPresent()) {
123	                        throw ApiException.conflict("已存在待接受的交接，不能重复发起");
124	                    }
125	                    Instant now = Instant.now();
126	                    incidents.insertTransfer(new IncidentTransfer(0L, incident.id(),
127	                            incident.commander(), toCommander, TransferStatus.PENDING, now, null));
128	                    return toTransferView(incidents.findPendingTransfer(incident.id()).orElseThrow());
129	                });
130	    }
131	
132	    /**
133	     * 接受交接：仅待接受目标人可接受；接受后原子切换当前指挥人。
134	     * RESOLVED/CLOSED 禁止接受；待接受期间目标人无其他操作权限。
135	     */
136	    @Transactional
137	    public IncidentView acceptTransfer(String incidentKey, String actor, TransferAcceptRequest req) {
138	        String commandKey = requireText(req.commandKey(), "commandKey");
139	        Incident incident = lockIncident(incidentKey);
140	        return runIdempotent(commandKey, "transfer_accept", hash(incidentKey, actor), IncidentView.class,
141	                () -> {
142	                    if (incident.status() == IncidentStatus.RESOLVED
143	                            || incident.status() == IncidentStatus.CLOSED) {
144	                        throw ApiException.illegalTransition(
145	                                incident.status() + " 状态不允许接受交接");
146	                    }
147	                    IncidentTransfer pending = incidents.findPendingTransfer(incident.id())
148	                            .orElseThrow(() -> ApiException.conflict("当前没有待接受的交接"));
149	                    if (!pending.toCommander().equals(actor)) {
150	                        throw ApiException.conflict("只有交接目标人 " + pending.toCommander() + " 能接受交接");
151	                    }
152	                    Instant now = Instant.now();
153	                    incidents.acceptTransfer(pending.id(), now);
154	                    incidents.updateState(incident.id(), incident.status(), pending.toCommander(), now);
155	                    return toView(incidents.findByKey(incidentKey).orElseThrow(), null);
156	                });
157	    }
158	
159	    /**
160	     * 追加处置记录：仅当前指挥人可写；CLOSED 后禁止写入。
161	     * actionKey 事件内唯一：同键同内容幂等返回首次记录，同键不同内容返回 409。
162	     */
163	    @Transactional
164	    public ActionView addAction(String incidentKey, String actor, ActionRequest req) {
165	        String commandKey = requireText(req.commandKey(), "commandKey");
166	        String actionKey = requireText(req.actionKey(), "actionKey");
167	        String actionType = requireText(req.actionType(), "actionType");
168	        String note = requireText(req.note(), "note");
169	        if (req.occurredAt() == null) {
170	            throw ApiException.badRequest("occurredAt 不能为空");
171	        }
172	        Instant occurredAt = req.occurredAt().truncatedTo(ChronoUnit.MICROS);
173	        Incident incident = lockIncident(incidentKey);
174	        return runIdempotent(commandKey, "action",
175	                hash(incidentKey, actor, actionKey, actionType, note, occurredAt.toString()),
176	                ActionView.class, () -> {
177	                    requireCommander(incident, actor);
178	                    if (incident.status() == IncidentStatus.CLOSED) {
179	                        throw ApiException.illegalTransition("事件已关闭，不能再追加处置记录");
180	                    }
181	                    var existing = incidents.findAction(incident.id(), actionKey);
182	                    if (existing.isPresent()) {
183	                        IncidentAction found = existing.get();
184	                        if (!found.sameContent(actionType, note, occurredAt)) {
185	                            throw ApiException.conflict("actionKey 已被不同内容使用: " + actionKey);
186	                        }
187	                        return toActionView(found);
188	                    }
189	                    Instant now = Instant.now();
190	                    incidents.insertAction(new IncidentAction(0L, incident.id(), actionKey, actionType,
191	                            note, occurredAt, actor, now));
192	                    return toActionView(incidents.findAction(incident.id(), actionKey).orElseThrow());
193	                });
194	    }
195	
196	    /**
197	     * 状态变更：仅当前指挥人可操作，仅允许 COMMANDING→CONTAINED→RESOLVED→CLOSED 逐级前进。
198	     */
199	    @Transactional
200	    public IncidentView changeStatus(String incidentKey, String actor, StatusRequest req) {
201	        String commandKey = requireText(req.commandKey(), "commandKey");
202	        String target = requireText(req.targetStatus(), "targetStatus");
203	        IncidentStatus targetStatus;
204	        try {
205	            targetStatus = IncidentStatus.valueOf(target);
206	        } catch (IllegalArgumentException e) {
207	            throw ApiException.badRequest("未知目标状态: " + target);
208	        }
209	        Incident incident = lockIncident(incidentKey);
210	        return runIdempotent(commandKey, "status", hash(incidentKey, actor, target),
211	                IncidentView.class, () -> {
212	                    requireCommander(incident, actor);
213	                    IncidentStatus next = incident.status().next();
214	                    if (next == null || next != targetStatus) {
215	                        throw ApiException.illegalTransition(
216	                                "不允许从 " + incident.status() + " 流转到 " + targetStatus);
217	                    }
218	                    Instant now = Instant.now();
219	                    incidents.updateState(incident.id(), targetStatus, incident.commander(), now);
220	                    incidents.insertStatusChange(new StatusChange(0L, incident.id(),
221	                            incident.status(), targetStatus, actor, now));
222	                    return toView(incidents.findByKey(incidentKey).orElseThrow(), null);
223	                });
224	    }
225	
226	    /**
227	     * 查询事件当前状态（含当前指挥人与待接受交接目标人）。
228	     */
229	    @Transactional(readOnly = true)
230	    public IncidentView get(String incidentKey) {
231	        Incident incident = incidents.findByKey(incidentKey)
232	                .orElseThrow(() -> ApiException.notFound("事件不存在: " + incidentKey));
233	        String pendingTo = incidents.findPendingTransfer(incident.id())
234	                .map(IncidentTransfer::toCommander).orElse(null);
235	        return toView(incident, pendingTo);
236	    }
237	
238	    /**
239	     * 查询完整历史：事件本体、状态流转、处置记录、交接记录。
240	     */
241	    @Transactional(readOnly = true)
242	    public HistoryView history(String incidentKey) {
243	        Incident incident = incidents.findByKey(incidentKey)
244	                .orElseThrow(() -> ApiException.notFound("事件不存在: " + incidentKey));
245	        String pendingTo = incidents.findPendingTransfer(incident.id())
246	                .map(IncidentTransfer::toCommander).orElse(null);
247	        List<StatusChangeView> statusHistory = incidents.listStatusHistory(incident.id()).stream()
248	                .map(s -> new StatusChangeView(
249	                        s.fromStatus() == null ? null : s.fromStatus().name(),
250	                        s.toStatus().name(), s.actor(), s.occurredAt()))
251	                .toList();
252	        List<ActionView> actions = incidents.listActions(incident.id()).stream()
253	                .map(this::toActionView).toList();
254	        List<TransferView> transfers = incidents.listTransfers(incident.id()).stream()
255	                .map(IncidentService::toTransferView).toList();
256	        return new HistoryView(toView(incident, pendingTo), statusHistory, actions, transfers);
257	    }
258	
259	    private Incident lockIncident(String incidentKey) {
260	        requireText(incidentKey, "incidentKey");
261	        return incidents.lockByKey(incidentKey)
262	                .orElseThrow(() -> ApiException.notFound("事件不存在: " + incidentKey));
263	    }
264	
265	    private static void requireCommander(Incident incident, String actor) {
266	        if (incident.commander() == null || !incident.commander().equals(actor)) {
267	            throw ApiException.conflict("只有当前指挥人 "
268	                    + (incident.commander() == null ? "(无)" : incident.commander()) + " 能执行该操作");
269	        }
270	    }
271	
272	    private static String requireText(String value, String field) {
273	        if (value == null || value.isBlank()) {
274	            throw ApiException.badRequest(field + " 不能为空");
275	        }
276	        return value.strip();
277	    }
278	
279	    /**
280	     * 幂等执行：同键同参重放首次响应，同键改参 409；并发同键由唯一约束串行化。
281	     */
282	    private <T> T runIdempotent(String commandKey, String operation, String requestHash,
283	                                Class<T> type, Supplier<T> business) {
284	        var existing = commandKeys.find(commandKey);
285	        if (existing.isPresent()) {
286	            return replay(existing.get(), operation, requestHash, type);
287	        }
288	        try {
289	            commandKeys.insertPlaceholder(commandKey, operation, requestHash, Instant.now());
290	        } catch (DuplicateKeyException e) {
291	            var committed = commandKeys.findForUpdate(commandKey)
292	                    .orElseThrow(() -> ApiException.conflict("commandKey 处理冲突: " + commandKey));
293	            return replay(committed, operation, requestHash, type);
294	        }
295	        T result = business.get();
296	        commandKeys.fillResponse(commandKey, 200, toJson(result));
297	        return result;
298	    }
299	
300	    private <T> T replay(CommandKeyRecord record, String operation, String requestHash, Class<T> type) {
301	        if (!record.operation().equals(operation) || !record.requestHash().equals(requestHash)) {
302	            throw ApiException.conflict("commandKey 已被不同参数的请求使用: " + record.commandKey());
303	        }
304	        if (record.responseBody() == null) {
305	            throw ApiException.conflict("commandKey 正在处理中: " + record.commandKey());
306	        }
307	        try {
308	            return objectMapper.readValue(record.responseBody(), type);
309	        } catch (JsonProcessingException e) {
310	            throw new IllegalStateException("幂等响应反序列化失败", e);
311	        }
312	    }
313	
314	    private String toJson(Object value) {
315	        try {
316	            return objectMapper.writeValueAsString(value);
317	        } catch (JsonProcessingException e) {
318	            throw new IllegalStateException("响应序列化失败", e);
319	        }
320	    }
321	
322	    private static String hash(String... parts) {
323	        try {
324	            MessageDigest digest = MessageDigest.getInstance("SHA-256");
325	            byte[] out = digest.digest(String.join(SEP, parts).getBytes(StandardCharsets.UTF_8));
326	            return HexFormat.of().formatHex(out);
327	        } catch (NoSuchAlgorithmException e) {
328	            throw new IllegalStateException(e);
329	        }
330	    }
331	
332	    private IncidentView toView(Incident incident, String pendingTransferTo) {
333	        return new IncidentView(incident.incidentKey(), incident.severity(), incident.summary(),
334	                incident.reporter(), incident.status().name(), incident.commander(), pendingTransferTo,
335	                incident.createdAt(), incident.updatedAt());
336	    }
337	
338	    private ActionView toActionView(IncidentAction action) {
339	        return new ActionView(action.actionKey(), action.actionType(), action.note(),
340	                action.occurredAt(), action.actor(), action.createdAt());
341	    }
342	
343	    private static TransferView toTransferView(IncidentTransfer transfer) {
344	        return new TransferView(transfer.id(), transfer.fromCommander(), transfer.toCommander(),
345	                transfer.status().name(), transfer.createdAt(), transfer.acceptedAt());
346	    }
347	}
