17	/**
18	 * 事件及关联表（处置记录、交接单、状态历史）的 JDBC 仓储。
19	 * 所有写路径先以 FOR UPDATE 锁定事件行，保证同一事件的并发写按事务提交顺序生效。
20	 */
21	@Repository
22	public class IncidentRepository {
23	
24	    private final JdbcTemplate jdbc;
25	
26	    public IncidentRepository(JdbcTemplate jdbc) {
27	        this.jdbc = jdbc;
28	    }
29	
30	    private static final RowMapper<Incident> INCIDENT_MAPPER = (rs, n) -> mapIncident(rs);
31	    private static final RowMapper<IncidentAction> ACTION_MAPPER = (rs, n) -> new IncidentAction(
32	            rs.getLong("id"), rs.getLong("incident_id"), rs.getString("action_key"),
33	            rs.getString("action_type"), rs.getString("note"),
34	            rs.getTimestamp("occurred_at").toInstant(), rs.getString("actor"),
35	            rs.getTimestamp("created_at").toInstant());
36	    private static final RowMapper<IncidentTransfer> TRANSFER_MAPPER = (rs, n) -> new IncidentTransfer(
37	            rs.getLong("id"), rs.getLong("incident_id"), rs.getString("from_commander"),
38	            rs.getString("to_commander"), TransferStatus.valueOf(rs.getString("status")),
39	            rs.getTimestamp("created_at").toInstant(),
40	            rs.getTimestamp("accepted_at") == null ? null : rs.getTimestamp("accepted_at").toInstant());
41	    private static final RowMapper<StatusChange> STATUS_MAPPER = (rs, n) -> new StatusChange(
42	            rs.getLong("id"), rs.getLong("incident_id"),
43	            rs.getString("from_status") == null ? null : IncidentStatus.valueOf(rs.getString("from_status")),
44	            IncidentStatus.valueOf(rs.getString("to_status")),
45	            rs.getString("actor"), rs.getTimestamp("occurred_at").toInstant());
46	
47	    private static Incident mapIncident(ResultSet rs) throws SQLException {
48	        return new Incident(rs.getLong("id"), rs.getString("incident_key"), rs.getString("severity"),
49	                rs.getString("summary"), rs.getString("reporter"),
50	                IncidentStatus.valueOf(rs.getString("status")), rs.getString("commander"),
51	                rs.getTimestamp("created_at").toInstant(), rs.getTimestamp("updated_at").toInstant());
52	    }
53	
54	    /**
55	     * 按业务键查询事件（不加锁），用于只读场景。
56	     */
57	    public Optional<Incident> findByKey(String incidentKey) {
58	        List<Incident> rows = jdbc.query("SELECT * FROM incidents WHERE incident_key = ?",
59	                INCIDENT_MAPPER, incidentKey);
60	        return rows.stream().findFirst();
61	    }
62	
63	    /**
64	     * 按业务键查询并锁定事件行（SELECT ... FOR UPDATE），用于写路径串行化。
65	     */
66	    public Optional<Incident> lockByKey(String incidentKey) {
67	        List<Incident> rows = jdbc.query("SELECT * FROM incidents WHERE incident_key = ? FOR UPDATE",
68	                INCIDENT_MAPPER, incidentKey);
69	        return rows.stream().findFirst();
70	    }
71	
72	    /**
73	     * 插入新事件，初始状态 REPORTED、无指挥人，返回生成主键。
74	     */
75	    public long insert(Incident incident) {
76	        KeyHolder keys = new GeneratedKeyHolder();
77	        jdbc.update(con -> {
78	            var ps = con.prepareStatement(
79	                    "INSERT INTO incidents (incident_key, severity, summary, reporter, status, commander,"
80	                            + " created_at, updated_at) VALUES (?,?,?,?,?,?,?,?)",
81	                    Statement.RETURN_GENERATED_KEYS);
82	            ps.setString(1, incident.incidentKey());
83	            ps.setString(2, incident.severity());
84	            ps.setString(3, incident.summary());
85	            ps.setString(4, incident.reporter());
86	            ps.setString(5, incident.status().name());
87	            ps.setString(6, incident.commander());
88	            ps.setTimestamp(7, Timestamp.from(incident.createdAt()));
89	            ps.setTimestamp(8, Timestamp.from(incident.updatedAt()));
90	            return ps;
91	        }, keys);
92	        return keys.getKey().longValue();
93	    }
94	
95	    /**
96	     * 更新事件状态与指挥人（commander 可为 null 表示不变更时传入原值）。
97	     */
98	    public void updateState(long id, IncidentStatus status, String commander, Instant updatedAt) {
99	        jdbc.update("UPDATE incidents SET status = ?, commander = ?, updated_at = ? WHERE id = ?",
100	                status.name(), commander, Timestamp.from(updatedAt), id);
101	    }
102	
103	    /**
104	     * 追加处置记录，返回生成主键。
105	     */
106	    public long insertAction(IncidentAction action) {
107	        KeyHolder keys = new GeneratedKeyHolder();
108	        jdbc.update(con -> {
109	            var ps = con.prepareStatement(
110	                    "INSERT INTO incident_actions (incident_id, action_key, action_type, note, occurred_at,"
111	                            + " actor, created_at) VALUES (?,?,?,?,?,?,?)",
112	                    Statement.RETURN_GENERATED_KEYS);
113	            ps.setLong(1, action.incidentId());
114	            ps.setString(2, action.actionKey());
115	            ps.setString(3, action.actionType());
116	            ps.setString(4, action.note());
117	            ps.setTimestamp(5, Timestamp.from(action.occurredAt()));
118	            ps.setString(6, action.actor());
119	            ps.setTimestamp(7, Timestamp.from(action.createdAt()));
120	            return ps;
121	        }, keys);
122	        return keys.getKey().longValue();
123	    }
124	
125	    /**
126	     * 按事件与 actionKey 查询处置记录，用于幂等比对。
127	     */
128	    public Optional<IncidentAction> findAction(long incidentId, String actionKey) {
129	        List<IncidentAction> rows = jdbc.query(
130	                "SELECT * FROM incident_actions WHERE incident_id = ? AND action_key = ?",
131	                ACTION_MAPPER, incidentId, actionKey);
132	        return rows.stream().findFirst();
133	    }
134	
135	    /**
136	     * 查询事件全部处置记录，按落库顺序返回。
137	     */
138	    public List<IncidentAction> listActions(long incidentId) {
139	        return jdbc.query("SELECT * FROM incident_actions WHERE incident_id = ? ORDER BY id",
140	                ACTION_MAPPER, incidentId);
141	    }
142	
143	    /**
144	     * 创建交接单（PENDING），返回生成主键。
